-- 3. leak-hero-db
insert into public.leaks (id, slug, leak_number, sort_order, status, publish_at, featured, data)
values (
  'leak-hero-db', 'que-hacer-cuando-se-expone-una-base-de-datos', null, 2, 'published',
  '2026-10-14T00:00:00-05:00', false,
  $dp${"id":"leak-hero-db","title":"Qué hacer cuando se expone una base de datos","slug":"que-hacer-cuando-se-expone-una-base-de-datos","category":"investigaciones","categoryLabel":"ANÁLISIS","severity":"alto","date":"14 Octubre, 2026","readTime":"7 min de lectura","author":"Tin9o (@Tin9o)","authorRole":"Especialista en Inteligencia OSINT & Brechas","authorTelegram":"Tin9o","imageUrl":"/imagenes/banner-filtraciones.png","summary":"Protocolo inmediato y exhaustivo de respuesta ante incidentes de exfiltración de bases de datos masivas: verificación de integridad, contención de credenciales y auditoría de accesos no autorizados.","affectedScope":"Bases de datos SQL/NoSQL & credenciales expuestas","compromisedData":["Usuarios y contraseñas hasheadas/planas","DNI y datos personales sensibles","Historial de transacciones y compras","Tokens de API y llaves de servicio"],"tags":["#BaseDeDatos","#DataBreach","#ForenseDigital","#RespuestaAIncidentes","#OSINT"],"featured":false,"content":["Cuando una base de datos corporativa o de un servicio en línea queda expuesta en internet —ya sea por un error en la configuración de permisos (como buckets S3 públicos o clústeres de Elasticsearch desprotegidos) o por una inyección SQL maliciosa— el tiempo de reacción es el factor más determinante para mitigar el impacto.","El primer paso consiste en validar la veracidad y frescura de la filtración. En los foros de la dark web abundan los \"combos\" reciclados de filtraciones antiguas combinadas bajo nuevos nombres comerciales. Mediante técnicas OSINT y cotejo de marcas de tiempo (timestamps), es posible determinar si la fuga corresponde a eventos recientes o a listas consolidadas del pasado.","El segundo paso innegociable es la revocación forzosa de sesiones activas y la rotación inmediata de secretos y llaves de servicio (API keys, certificados SSL y credenciales de base de datos). Los atacantes suelen buscar tokens de acceso con privilegios elevados para garantizar persistencia silenciosa en la infraestructura.","Para los usuarios finales afectados, la recomendación principal es cambiar de inmediato las contraseñas en todos los servicios donde se haya utilizado la misma combinación de correo y clave, activar autenticación de dos factores (2FA) mediante aplicaciones TOTP (evitando SMS) y monitorizar posibles intentos de suplantación o phishing dirigido."]}$dp$::jsonb
)
