-- 4. leak-fake-alert
insert into public.leaks (id, slug, leak_number, sort_order, status, publish_at, featured, data)
values (
  'leak-fake-alert', 'como-reconocer-una-alerta-falsa', null, 3, 'published',
  '2026-10-13T00:00:00-05:00', false,
  $dp${"id":"leak-fake-alert","title":"Cómo reconocer una alerta falsa","slug":"como-reconocer-una-alerta-falsa","category":"guias","categoryLabel":"GUÍA","severity":"medio","date":"13 Octubre, 2026","readTime":"4 min","author":"Redacción DP","authorRole":"Ciberseguridad & Prevención","authorTelegram":"DESCUENTOSPER2","imageUrl":"/imagenes/banner-phishing.png","summary":"Identifica las tácticas de alarmismo psicológico y phishing con supuestas alertas rojas que buscan forzar clics desesperados o la descarga de troyanos.","affectedScope":"Navegación web y notificaciones push fraudulentas","compromisedData":["Ingeniería social de alta urgencia","Ventanas emergentes falsas con logos de antivirus","Phishing para captura de credenciales"],"tags":["#FakeAlert","#Scam","#Phishing","#EducacionDigital"],"featured":false,"content":["Las alertas falsas son uno de los vectores más comunes de engaño digital. Suelen presentarse como ventanas emergentes en el navegador con sirenas animadas, logos apócrifos de antivirus reconocidos o avisos judiciales que aseguran que tu equipo ha sido infectado con decenas de virus.","El objetivo detrás de estas pantallas es generar angustia y apresurar a la víctima para que llame a números de soporte falsos, compre licencias fraudulentas o instale programas de control remoto tipo AnyDesk o TeamViewer que entregan el control total del equipo al estafador.","Cómo identificar una alerta falsa: (1) Revisa la barra de direcciones; si la alerta aparece en una página web desconocida y no desde la aplicación nativa de tu antivirus instalado, es 100% falsa. (2) Desconfía de temporizadores regresivos que amenazan con bloquear tu disco duro. (3) Nunca llames a números telefónicos incluidos en mensajes emergentes."]}$dp$::jsonb
)
