-- 5. leak-report-reveal
insert into public.leaks (id, slug, leak_number, sort_order, status, publish_at, featured, data)
values (
  'leak-report-reveal', 'que-revela-un-reporte-de-filtracion', null, 4, 'published',
  '2026-10-12T00:00:00-05:00', false,
  $dp${"id":"leak-report-reveal","title":"Qué revela un reporte de filtración","slug":"que-revela-un-reporte-de-filtracion","category":"filtraciones","categoryLabel":"ANÁLISIS","severity":"alto","date":"12 Octubre, 2026","readTime":"6 min","author":"Tin9o (@Tin9o)","authorRole":"Especialista en Inteligencia OSINT & Brechas","authorTelegram":"Tin9o","imageUrl":"/imagenes/card-investigacion.png","summary":"Aprende a interpretar hashes criptográficos, metadatos de exfiltración, volcados SQL y campos comprometidos para medir el verdadero alcance de una filtración.","affectedScope":"Auditoría y análisis técnico de volcados de datos","compromisedData":["Cotejo de registros cruzados","Volcados SQL y colecciones JSON","Hashes MD5, SHA-1 y bcrypt expuestos"],"tags":["#DataBreach","#HashCracking","#AnalisisTecnico","#OSINT"],"featured":false,"content":["Un reporte de filtración auténtico contiene elementos técnicos específicos que permiten certificar su procedencia. Entre ellos destacan los volcados de esquemas relacionales (tablas DDL), los identificadores únicos autoincrementales y los metadatos de exportación propios de motores como MySQL, PostgreSQL u Oracle.","Para los analistas de seguridad, el examen de los campos comprometidos revela si los atacantes obtuvieron hashes con sal (salts) o contraseñas en texto claro. Los algoritmos débiles como MD5 o SHA-1 son vulnerables a tablas arcoíris en minutos, mientras que bcrypt o Argon2 ofrecen mayor resistencia temporal.","Desmitificar los anuncios de filtraciones exige prudencia técnica: muchos actores maliciosos inflan las cifras agregando datos sintéticos o duplicando registros para exigir rescates elevados a empresas desprevenidas."]}$dp$::jsonb
)
