-- 6. leak-three-steps
insert into public.leaks (id, slug, leak_number, sort_order, status, publish_at, featured, data)
values (
  'leak-three-steps', '3-pasos-ante-un-incidente-de-seguridad', null, 5, 'published',
  '2026-10-11T00:00:00-05:00', false,
  $dp${"id":"leak-three-steps","title":"3 pasos ante un incidente de seguridad","slug":"3-pasos-ante-un-incidente-de-seguridad","category":"ciberseguridad","categoryLabel":"PROTECCIÓN","severity":"alto","date":"11 Octubre, 2026","readTime":"5 min","author":"Redacción DP","authorRole":"Respuesta Rápida a Incidentes","authorTelegram":"DESCUENTOSPER2","imageUrl":"/imagenes/leak-shield-lock.jpg","summary":"Plan de acción en tres fases para aislar el equipo comprometido, preservar la evidencia forense y restaurar la operatividad sin perder datos.","affectedScope":"Equipos endpoint, redes domésticas y cuentas críticas","compromisedData":["Aislamiento de red inmediato","Recolección de logs de memoria y procesos","Cambio de credenciales maestras y restablecimiento"],"tags":["#IncidentResponse","#SeguridadDigital","#PrimerosAuxiliosIT","#Defensa"],"featured":false,"content":["Ante la sospecha o confirmación de una intrusión en tu estación de trabajo o servidor, la improvisación es el peor enemigo. Los primeros sesenta minutos tras el incidente definen si el impacto será contenido o catastrófico.","Paso 1: Desconexión física inmediata de la red (cable Ethernet y Wi-Fi). No apagues el equipo abruptamente para evitar la pérdida de evidencia volátil en la memoria RAM que servirá al peritaje forense.","Paso 2: Desde un dispositivo alternativo seguro y no comprometido, procede al cambio de credenciales de acceso a correos principales, servicios en la nube y banca electrónica.","Paso 3: Realiza un escaneo exhaustivo con herramientas antimalware reconocidas en modo sin conexión y reinstala el sistema operativo si se detectó la ejecución de rootkits o troyanos de acceso remoto (RAT)."]}$dp$::jsonb
)
