-- 7. leak-understand-exposure
insert into public.leaks (id, slug, leak_number, sort_order, status, publish_at, featured, data)
values (
  'leak-understand-exposure', 'como-entender-el-nivel-de-exposicion-de-tus-datos', null, 6, 'published',
  '2026-10-10T00:00:00-05:00', false,
  $dp${"id":"leak-understand-exposure","title":"Cómo entender el nivel de exposición de tus datos","slug":"como-entender-el-nivel-de-exposicion-de-tus-datos","category":"filtraciones","categoryLabel":"FILTRACIONES","severity":"medio","date":"10 Octubre, 2026","readTime":"5 min de lectura","author":"Tin9o (@Tin9o)","authorRole":"Especialista en Inteligencia OSINT & Brechas","authorTelegram":"Tin9o","imageUrl":"/imagenes/leak-doc-analysis.jpg","summary":"Conoce los distintos niveles de riesgo según el tipo de datos expuestos: desde el correo electrónico público hasta el DNI, celular y huellas biométricas.","affectedScope":"Perfiles de usuario y bases de datos personales peruanas","compromisedData":["Nivel 1: Datos de contacto públicos (correo, alias)","Nivel 2: Documentos oficiales (DNI, fecha de nacimiento)","Nivel 3: Credenciales de acceso y tokens","Nivel 4: Datos financieros y biométricos"],"tags":["#NivelDeRiesgo","#ExposicionDeDatos","#Privacidad","#DNI"],"featured":false,"content":["No todas las filtraciones conllevan el mismo nivel de peligro para el usuario común. Clasificar la severidad del incidente es clave para priorizar los esfuerzos defensivos sin caer en pánico.","Una exposición de solo correos y nombres (Nivel 1) incrementa el spam y el phishing genérico, pero no compromete de inmediato tus fondos ni tus cuentas si cuentas con contraseñas robustas.","Por el contrario, la filtración simultánea de DNI, teléfono, dirección residencial y clave hasheada (Niveles 2 y 3) habilita ataques de SIM swapping, fraude por suplantación en operadores de telefonía y apertura no autorizada de créditos financieros.","En Perú, la recurrente circulación de padrones con información del Reniec y Sunat exige a los ciudadanos verificar periódicamente su reporte en centrales de riesgo para detectar a tiempo créditos no solicitados."]}$dp$::jsonb
)
