-- 8. leak-suspicious-email
insert into public.leaks (id, slug, leak_number, sort_order, status, publish_at, featured, data)
values (
  'leak-suspicious-email', 'senales-de-un-correo-sospechoso', null, 7, 'published',
  '2026-10-09T00:00:00-05:00', false,
  $dp${"id":"leak-suspicious-email","title":"Señales de un correo sospechoso","slug":"senales-de-un-correo-sospechoso","category":"ciberseguridad","categoryLabel":"CIBERSEGURIDAD","severity":"medio","date":"09 Octubre, 2026","readTime":"6 min de lectura","author":"Redacción DP","authorRole":"Especialista Anti-Phishing","authorTelegram":"DESCUENTOSPER2","imageUrl":"/imagenes/banner-escudo.png","summary":"Encabezados fraudulentos, spoofing de dominios bancarios y lenguaje de coacción psicológica: radiografía de una campaña de phishing moderna.","affectedScope":"Bandejas de correo corporativo y personal","compromisedData":["Credenciales de correo electrónico","Archivos adjuntos maliciosos (ISO, ZIP, PDF)","Enlaces señuelo a plataformas clonadas"],"tags":["#Phishing","#EmailSecurity","#IngenieriaSocial","#Ciberdefensa"],"featured":false,"content":["El phishing sigue siendo el punto de entrada de más del 80% de los ciberataques contra personas y organizaciones. Aunque los filtros antispam modernos bloquean millones de mensajes cada día, las campañas dirigidas utilizan técnicas cada vez más sofisticadas.","Entre las principales señales de alarma se encuentran: discrepancias entre el nombre visible del remitente y la dirección real del correo electrónico en el encabezado, solicitudes urgentes de pago o verificación bajo amenaza de bloqueo inmediato, y enlaces que redirigen a dominios tipográficamente similares (typosquatting).","Adicionalmente, el adjunto de archivos comprimidos (.zip, .7z) o imágenes de disco (.iso) suele ocultar ejecutables maliciosos o troyanos tipo stealer listos para capturar contraseñas al primer clic.","Regla de oro: Si recibes una notificación de tu banco o proveedor de servicios solicitando verificar tus datos, nunca hagas clic en el enlace del correo; accede siempre escribiendo manualmente la dirección web oficial en tu navegador."]}$dp$::jsonb
